This is equivalent to calling `reset_at(Instant::now() + period)`.

# Examples

```
use tokio::time;

use std::time::Duration;

# #[tokio::main(flavor = "current_thread")]
# async fn main() {
let mut interval = time::interval(Duration::from_millis(100));

interval.tick().await;

