It will clone the owned `Arc<Semaphore>` to construct the new instance.

# Examples

```
use std::sync::Arc;
use tokio::sync::Semaphore;

let sem = Arc::new(Semaphore::new(3));

let mut p1 = sem.try_acquire_many_owned(3).unwrap();
